using DocumentFormat.OpenXml.Presentation;
using A = DocumentFormat.OpenXml.Drawing;

namespace OfficeIMO.PowerPoint {
    public partial class PowerPointSlide {
        /// <summary>
        ///     Appends a shape generated by the layout system from its markup, assigning a fresh id and a unique name
        ///     based on the generated one, and returns its tracked wrapper.
        /// </summary>
        internal PowerPointShape AppendLayoutShape(string markup, bool textBox) {
            ArgumentNullException.ThrowIfNull(markup);
            var shape = new Shape(markup);
            NonVisualDrawingProperties? properties = shape.NonVisualShapeProperties?.NonVisualDrawingProperties;
            if (properties != null) {
                properties.Id = AllocateShapeId();
                string baseName = string.IsNullOrWhiteSpace(properties.Name?.Value) ? "Shape" : properties.Name!.Value!;
                // A name that already carries its index ("Screenshot Annotation 2") is kept when it is unique.
                bool indexed = baseName.Length > 0 && char.IsDigit(baseName[baseName.Length - 1]);
                properties.Name = indexed && !ShapeList.Any(s => s.Name == baseName) ? baseName : GenerateUniqueName(baseName);
            }

            CommonSlideData data = SlideRoot.CommonSlideData ??= new CommonSlideData(new ShapeTree());
            ShapeTree tree = data.ShapeTree ??= new ShapeTree();
            tree.AppendChild(shape);
            return textBox
                ? TrackShape(new PowerPointTextBox(shape, SlidePart))
                : TrackShape(new PowerPointAutoShape(shape));
        }

        /// <summary>
        ///     A detached copy of a layout text frame, with the same relationship owner and slide as the source, for
        ///     the layout system to fill with copies of its paragraphs.
        /// </summary>
        internal static PowerPointTextBox CopyLayoutTextBox(PowerPointTextBox box) {
            var shape = (Shape)box.Element.CloneNode(true);
            var copy = box.RelationshipOwnerPart != null
                ? new PowerPointTextBox(shape, box.RelationshipOwnerPart)
                : new PowerPointTextBox(shape, box.SlidePart);
            if (box.OwnerSlide != null) copy.AttachTo(box.OwnerSlide, box.RelationshipOwnerPart);
            return copy;
        }

        /// <summary>Replaces the table of a layout-generated table frame with the table <paramref name="markup"/> describes.</summary>
        internal static void ReplaceLayoutTable(PowerPointTable table, string markup) {
            A.Table element = table.TableElement;
            A.GraphicData data = (A.GraphicData)element.Parent!;
            element.Remove();
            data.AppendChild(new A.Table(markup));
        }

        /// <summary>Name of the slide layout this slide uses, or null.</summary>
        internal string? SlideLayoutName => SlidePart.SlideLayoutPart?.SlideLayout?.CommonSlideData?.Name?.Value;
    }
}
